-- الخطوة BG2 (قرار المالك 18 نوفمبر): جملة السجلات المالية في مسودة الخصوصية (الإصدار 2) تطابق الحذف الفعلي —
-- تُحذف الطلبات والسندات مع بيانات المتدرب بعد 90 يومًا (الخطوة BB) بدل «للمدة التي يوجبها النظام». النص من src/policy_drafts.js.
update policies set body = replace(body, '- السجلات المالية والمحاسبية: للمدة التي يوجبها النظام، دون استعمالها في غير ذلك.', '- الطلبات وسندات الاستلام وإشعارات الاسترداد وصور الإيصالات: تُحذف مع بيانات المتدرب في المدد نفسها أعلاه.')
where slug = 'privacy' and status = 'draft' and position('- السجلات المالية والمحاسبية: للمدة التي يوجبها النظام، دون استعمالها في غير ذلك.' in body) > 0;
